import{_ as a,o as e,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"Crimson Project Update","description":"","frontmatter":{"title":"Crimson Project Update","date":"2026-07-09T00:00:00.000Z","updated":"2026-07-10T00:00:00.000Z","tags":["Crimson","OSD","性能优化","分布式存储","存储优化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Crimson_Project_Update.md","filePath":"posts/2026/Crimson_Project_Update.md","lastUpdated":null}'),l={name:"posts/2026/Crimson_Project_Update.md"};function i(s,r,n,d,c,h){return e(),t("div",null,[...r[0]||(r[0]=[o('<h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本次演讲对 Crimson 项目的当前进展进行了全面更新。Crimson 是一个持续多年的项目，旨在重新设计下一代 OSD 进程，以适应现代多核处理器架构。</p><h2 id="背景与动机" tabindex="-1">背景与动机 <a class="header-anchor" href="#背景与动机" aria-label="Permalink to &quot;背景与动机&quot;">​</a></h2><p>现代 CPU 的单核性能在过去 10~15 年已基本停止提升，服务器的计算能力提升主要依赖核心数量的增加——当前主流高端服务器已配置 256 核甚至更多。然而，传统的 Ceph OSD 代码库已有超过 20 年历史，其设计假设难以充分利用这种多核并行架构。</p><p>Crimson 的两大核心目标：</p><ol><li><strong>充分利用现代多核架构</strong>，实现更好的横向扩展性</li><li><strong>现代化代码库</strong>，引入过去 20 年涌现的新实践与新技术</li></ol><p>性能对比测试中，在 32 核服务器上，classic OSD 只能保持 24 个核心满负荷运行，而 Crimson 能让全部 32 个核心保持忙碌，等效于多利用了约 25% 的硬件资源。</p><h2 id="umbrella-版本关键进展" tabindex="-1">Umbrella 版本关键进展 <a class="header-anchor" href="#umbrella-版本关键进展" aria-label="Permalink to &quot;Umbrella 版本关键进展&quot;">​</a></h2><h3 id="打包与部署集成" tabindex="-1">打包与部署集成 <a class="header-anchor" href="#打包与部署集成" aria-label="Permalink to &quot;打包与部署集成&quot;">​</a></h3><ul><li>Crimson 现已集成进默认 RPM 包，不再需要单独安装额外的包集合</li><li>Cephadm 现已支持部署 Crimson 集群，操作体验与部署 classic 集群一致</li><li>Cephadm 支持 Crimson 的原生后端 <strong>Seastore</strong>（Crimson 对 BlueStore 的替代方案）</li></ul><p>上述改动显著降低了开发测试环境中试用 Crimson 的门槛，同时使 CI 流水线能够更方便地运行 Crimson 相关测试，Teuthology 测试覆盖率因此大幅提升。</p><h3 id="qos-与调度" tabindex="-1">QoS 与调度 <a class="header-anchor" href="#qos-与调度" aria-label="Permalink to &quot;QoS 与调度&quot;">​</a></h3><p><strong>mClock</strong> 调度器（此前已在 classic OSD 中引入）现已在 Crimson 中完整实现并支持。</p><h3 id="对象存储后端切换-bluestore-→-seastore" tabindex="-1">对象存储后端切换：BlueStore → Seastore <a class="header-anchor" href="#对象存储后端切换-bluestore-→-seastore" aria-label="Permalink to &quot;对象存储后端切换：BlueStore → Seastore&quot;">​</a></h3><p>这是过去一年最重大的变化：</p><ul><li>Seastore 的逻辑地址空间从 64 位扩展至 <strong>128 位</strong></li><li>Crimson 的全部测试现已默认运行在 Seastore 之上</li><li>使用 BlueStore 运行 Crimson 从&quot;常规做法&quot;变为&quot;例外情况&quot;——与一年前完全相反</li></ul><p>Seastore 的重要性在于它与 Crimson 其他组件采用相同的 <strong>polling + 多 CPU</strong> 架构，能够真正释放现代硬件多核扩展性的潜力。</p><h3 id="erasure-coding-支持" tabindex="-1">Erasure Coding 支持 <a class="header-anchor" href="#erasure-coding-支持" aria-label="Permalink to &quot;Erasure Coding 支持&quot;">​</a></h3><ul><li>Tentacle 版本仅支持副本池，Umbrella 版本中 Seastore 的 EC 支持已大量合并</li><li>Crimson 只支持新的 <strong>Fast EC</strong> 实现，不支持旧版 EC 代码</li><li>支持 Fast EC 的全部代码改动已合并，EC 功能正在进行 bring-up 工作，预计再过几个月即可正式可用</li></ul><h3 id="协议覆盖面扩展-cephfs-与-rgw" tabindex="-1">协议覆盖面扩展：CephFS 与 RGW <a class="header-anchor" href="#协议覆盖面扩展-cephfs-与-rgw" aria-label="Permalink to &quot;协议覆盖面扩展：CephFS 与 RGW&quot;">​</a></h3><p>RADOS API 接口庞大，RBD 只使用了其中的一个子集，而 CephFS 和 RGW 各自有其特有的协议细节。目前：</p><ul><li>Crimson 已测试覆盖 <strong>RBD、CephFS、RGW</strong> 三种客户端路径</li><li>对完整 RADOS 协议的支持置信度大幅提升</li></ul><h2 id="近期待完成工作" tabindex="-1">近期待完成工作 <a class="header-anchor" href="#近期待完成工作" aria-label="Permalink to &quot;近期待完成工作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>状态</th></tr></thead><tbody><tr><td>PG merging（已支持 splitting）</td><td>开发基本完成，即将合并</td></tr><tr><td>Erasure Coding 正式启用</td><td>预计数月内完成</td></tr><tr><td>Scrubbing 自动调度</td><td>当前只支持手动触发，调度器待实现</td></tr><tr><td>Seastore 写性能优化</td><td>持续攻关中</td></tr></tbody></table><h2 id="性能现状" tabindex="-1">性能现状 <a class="header-anchor" href="#性能现状" aria-label="Permalink to &quot;性能现状&quot;">​</a></h2><ul><li><strong>读性能</strong>：Crimson 在某些基准测试中达到 classic 的 <strong>3 倍</strong>，表现令人满意</li><li><strong>写性能</strong>：目前仍落后于 classic，改进空间较大 <ul><li>一年前写性能约为 classic 的 10%，目前已有所提升，但差距依然明显</li><li>尚未实现的几个已知优化点是主要瓶颈，不是&quot;无从下手&quot;的问题</li></ul></li></ul><p>社区成员 Jose 在 Crimson Slack 频道持续进行细粒度的性能分析，聚焦于写路径优化。Crimson OSD 也引入了一套全新的 metrics，部分指标与 classic 相似，部分为 Seastore 专有，配套工具链也在同步完善中。</p><h2 id="硬件支持" tabindex="-1">硬件支持 <a class="header-anchor" href="#硬件支持" aria-label="Permalink to &quot;硬件支持&quot;">​</a></h2><p>Crimson 同时针对 HDD 和 NVMe 进行了设计，提供两种 block manager：</p><ul><li><strong>Segment Manager</strong>：面向 HDD 及 zoned storage 场景（包括部分 QLC NVMe 设备）</li><li><strong>Random Block Manager</strong>：面向高性能 NVMe 存储</li></ul><p>设备类型可通过 CRUSH 中的 device class 自动识别。</p><h2 id="迁移路径展望" tabindex="-1">迁移路径展望 <a class="header-anchor" href="#迁移路径展望" aria-label="Permalink to &quot;迁移路径展望&quot;">​</a></h2><p>从 classic + BlueStore 向 Crimson 迁移将是一个<strong>多年渐进式</strong>过渡，与当年 FileStore → BlueStore 的迁移模式类似：</p><ul><li>早期采用者和新集群可以优先切换到 Crimson</li><li>已有集群可继续运行 classic，待时机成熟再迁移</li><li>两套方案将在相当长的时间内并行支持</li><li>一旦 Crimson 稳定，新特性开发重心将逐步转移至 Crimson，classic/BlueStore 进入维护状态</li></ul><h2 id="社区参与" tabindex="-1">社区参与 <a class="header-anchor" href="#社区参与" aria-label="Permalink to &quot;社区参与&quot;">​</a></h2><ul><li><strong>文档</strong>：已有完整的部署文档，建议从文档入手进行测试</li><li><strong>Issue tracker</strong>：Crimson backlog 公开可查</li><li><strong>Slack 频道</strong>：<code>#crimson</code>，适合提问和交流</li><li><strong>周会</strong>：Crimson 项目每周举行社区例会</li></ul><p>演讲者鼓励大家在<strong>开发/测试环境</strong>中试用 Crimson（勿在生产环境），并积极反馈问题——目前仍有调整窗口期，来自社区的反馈非常宝贵。</p>',37)])])}const p=a(l,[["render",i]]);export{m as __pageData,p as default};
